#!/usr/bin/env bash
# init_flags.sh — generate per-build opaque flag tokens (runtime-only, not
# committed in source). Writes a .env the compose stack reads. Run once before
# `docker compose up`. Re-run to rotate.
set -euo pipefail
cd "$(dirname "$0")/.."

rand() { head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

EASY="CTF{wire_$(rand)}"
MID="CTF{cant_see_me_$(rand)}"
GATE_TOKEN="gate-$(rand)"

cat > .env <<EOF
# generated by flags/init_flags.sh — do not commit
EASY_FLAG=${EASY}
MID_FLAG=${MID}
RELAY_KEY=RELAY-FACTORY-DEFAULT
GATE_TOKEN=${GATE_TOKEN}
BEACON_INTERVAL=5
EOF

echo "wrote .env with fresh EASY_FLAG / MID_FLAG."
echo "  easy (capture): ${EASY}"
echo "  mid  (go dark) : ${MID}"
